--
-- Name: session_feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.session_feedback (
    id integer NOT NULL,
    organization_id integer NOT NULL,
    session_id integer NOT NULL,
    user_id integer NOT NULL,
    rating_content integer NOT NULL,
    rating_trainer integer NOT NULL,
    rating_delivery integer NOT NULL,
    comment text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT session_feedback_rating_content_check CHECK (((rating_content >= 1) AND (rating_content <= 5))),
    CONSTRAINT session_feedback_rating_delivery_check CHECK (((rating_delivery >= 1) AND (rating_delivery <= 5))),
    CONSTRAINT session_feedback_rating_trainer_check CHECK (((rating_trainer >= 1) AND (rating_trainer <= 5)))
);


